import { UserFederatedIdentityRepository } from 'app/features/identity/user-federated-identity/repository/user-federated-identity-repository.service';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { UserFederatedIdentity } from 'app/features/identity/user-federated-identity/model/user-federated-identity.model';
