/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'user-federated-identity-view-import-action',
  standalone: false,
  templateUrl: './user-federated-identity-view-import-action.component.html',
})
export class UserFederatedIdentityViewImportActionComponent extends BaseImportAction<UserFederatedIdentity> {
  protected readonly scope = 'identity/user-federated-identity';
  protected readonly repository = inject(UserFederatedIdentityRepository);
  private readonly userRepository = inject(UserRepository);
  private readonly loginProviderRepository = inject(TenantLoginProviderRepository);

  readonly definition: ImportDefinition<UserFederatedIdentity> = {
    storageKey: 'identity.user-federated-identity',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['loginProvider', 'subject'],
    columns: USER_FEDERATED_IDENTITY_EXCEL_COLUMNS,
    sensitive: USER_FEDERATED_IDENTITY_EXCEL_SENSITIVE,
    references: {
      user: {
        resolve: (text) =>
          this.userRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
      loginProvider: {
        resolve: (text) =>
          this.loginProviderRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    display: (values) => String(values.subject ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            loginProvider: values.loginProvider?.$ref ? [values.loginProvider.$ref] : undefined,
            subject: values.subject,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  (!values.loginProvider?.$ref || item.loginProvider?.$ref === values.loginProvider.$ref) &&
                  item.subject === values.subject,
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
